class Solution {
  public boolean canDivideIntoSubsequences(int[] nums, int k) {
    // the most frequent value needs its own sequence per copy; each needs k elements
    int run = 1, maxRun = 1;
    for (int i = 1; i < nums.length; i++) {
      run = nums[i] == nums[i - 1] ? run + 1 : 1;
      maxRun = Math.max(maxRun, run);
    }
    return (long) maxRun * k <= nums.length;
  }
}
